{"file_path":"src/input.js","content":"import * as fs from 'node:fs'

export const MODES = ['merge', 'merge2', 'regions']

export class Failure extends Error {}

/** Read every byte of standard input as text. */
export function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch (err) {
    if (err && (err.code === 'EAGAIN' || err.code === 'EOF')) return ''
    throw err
  }
}

/**
 * Split the raw input into lines: newline separates lines and the single empty
 * tail a trailing newline leaves is dropped.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Split the lines into the three documents that `%%%` lines separate: mine,
 * the base, and theirs.
 */
export function splitParts(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) {
    throw new Failure('error: expected three parts separated by %%%')
  }
  return parts
}

/** Pick the mode out of the command line arguments. */
export function parseMode(argv) {
  if (argv.length !== 1 || !MODES.includes(argv[0])) {
    throw new Failure('error: usage: cli.js merge|merge2|regions')
  }
  return argv[0]
}
"}

