{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence over whole lines, comparing lines as exact
 * strings, and the changes such a subsequence leaves behind.
 */

/**
 * Lengths of the longest common subsequence of every pair of suffixes:
 * table[i * (m + 1) + j] is the length for a[i..] and b[j..].
 */
function suffixLengths(a, b) {
  const n = a.length
  const m = b.length
  const table = new Int32Array((n + 1) * (m + 1))
  for (let i = n - 1; i >= 0; i--) {
    const row = i * (m + 1)
    const next = (i + 1) * (m + 1)
    for (let j = m - 1; j >= 0; j--) {
      table[row + j] =
        a[i] === b[j]
          ? table[next + j + 1] + 1
          : Math.max(table[next + j], table[row + j + 1])
    }
  }
  return table
}

/**
 * The matches of the longest common subsequence whose matches come earliest:
 * walking both documents from the start, take a match whenever the two current
 * lines are equal, and otherwise advance the side whose remaining subsequence
 * is at least as long as the other's, preferring to advance the base on a tie.
 */
export function matchLines(base, side) {
  const n = base.length
  const m = side.length
  const table = suffixLengths(base, side)
  const width = m + 1
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (table[(i + 1) * width + j] >= table[i * width + j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * The changes between the base and one side: every stretch the common
 * subsequence does not cover, as a run of base lines replaced by a run of the
 * side's lines.
 */
export function changesAgainstBase(base, side) {
  const matches = matchLines(base, side)
  const changes = []
  let baseAt = 0
  let sideAt = 0
  const emit = (baseEnd, sideEnd) => {
    if (baseAt !== baseEnd || sideAt !== sideEnd) {
      changes.push({ baseStart: baseAt, baseEnd, sideStart: sideAt, sideEnd })
    }
  }
  for (const [baseIndex, sideIndex] of matches) {
    emit(baseIndex, sideIndex)
    baseAt = baseIndex + 1
    sideAt = sideIndex + 1
  }
  emit(base.length, side.length)
  return changes
}
"}

