{"file_path":"src/render.js","content":"/** Turn merged regions into the output of each mode. */

export function renderMerge(regions, withBase) {
  const lines = []
  for (const region of regions) {
    if (region.kind === 'conflict') {
      lines.push('<<<<<<< mine')
      lines.push(...region.mineLines)
      if (withBase) {
        lines.push('||||||| base')
        lines.push(...region.baseLines)
      }
      lines.push('=======')
      lines.push(...region.theirsLines)
      lines.push('>>>>>>> theirs')
    } else {
      lines.push(...region.lines)
    }
  }
  return lines
}

export function renderRegions(regions) {
  return regions.map(region =>
    region.kind === 'conflict'
      ? `conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`
      : `${region.kind} ${region.lines.length}`,
  )
}

export function hasConflict(regions) {
  return regions.some(region => region.kind === 'conflict')
}
