import { changesAgainstBase } from './diff.js'

const MINE = 'mine'
const THEIRS = 'theirs'

function sameLines(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * All changes of both sides, ordered by where they start in the base, with the
 * changes from mine before the changes from theirs at the same place.
 */
function orderedChanges(mineChanges, theirsChanges) {
  const all = [
    ...mineChanges.map((change, order) => ({ ...change, side: MINE, order })),
    ...theirsChanges.map((change, order) => ({ ...change, side: THEIRS, order })),
  ]
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side !== b.side) return a.side === MINE ? -1 : 1
    return a.order - b.order
  })
  return all
}

/** Group the changes into the regions of the base that they touch. */
function groupRegions(changes) {
  const regions = []
  let at = 0
  while (at < changes.length) {
    const first = changes[at]
    const region = {
      baseStart: first.baseStart,
      baseEnd: first.baseEnd,
      changes: [first],
    }
    at++
    while (at < changes.length && changes[at].baseStart <= region.baseEnd) {
      const next = changes[at]
      region.changes.push(next)
      if (next.baseEnd > region.baseEnd) region.baseEnd = next.baseEnd
      at++
    }
    regions.push(region)
  }
  return regions
}

/**
 * The lines one side puts in place of a region touched by several changes: from
 * the smallest start of its own changes, moved back by however far the region
 * begins before those changes do in the base, to the largest end of its own
 * changes, moved forward by however far the region ends after them.
 */
function sideLines(region, side, sideDoc, base) {
  const own = region.changes.filter(change => change.side === side)
  if (own.length === 0) return base.slice(region.baseStart, region.baseEnd)
  let sideStart = Infinity
  let sideEnd = -Infinity
  let baseStart = Infinity
  let baseEnd = -Infinity
  for (const change of own) {
    if (change.sideStart < sideStart) sideStart = change.sideStart
    if (change.sideEnd > sideEnd) sideEnd = change.sideEnd
    if (change.baseStart < baseStart) baseStart = change.baseStart
    if (change.baseEnd > baseEnd) baseEnd = change.baseEnd
  }
  const back = baseStart - region.baseStart
  const forward = region.baseEnd - baseEnd
  return sideDoc.slice(sideStart - back, sideEnd + forward)
}

/** Resolve one region into the lines the merge keeps, or into a conflict. */
function resolveRegion(region, mine, base, theirs) {
  const baseLines = base.slice(region.baseStart, region.baseEnd)

  if (region.changes.length === 1) {
    const only = region.changes[0]
    const doc = only.side === MINE ? mine : theirs
    return { kind: only.side, lines: doc.slice(only.sideStart, only.sideEnd) }
  }

  const mineLines = sideLines(region, MINE, mine, base)
  const theirsLines = sideLines(region, THEIRS, theirs, base)

  if (sameLines(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (sameLines(mineLines, baseLines)) return { kind: THEIRS, lines: theirsLines }
  if (sameLines(theirsLines, baseLines)) return { kind: MINE, lines: mineLines }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * The merge of the base into mine and theirs, as the ordered list of its
 * regions: stable stretches of the base and resolved or conflicting regions.
 */
export function mergeDocuments(mine, base, theirs) {
  const regions = groupRegions(
    orderedChanges(changesAgainstBase(base, mine), changesAgainstBase(base, theirs)),
  )

  const result = []
  let at = 0
  const stableUpTo = end => {
    if (end > at) result.push({ kind: 'stable', lines: base.slice(at, end) })
    at = end
  }

  for (const region of regions) {
    stableUpTo(region.baseStart)
    result.push(resolveRegion(region, mine, base, theirs))
    at = region.baseEnd
  }
  stableUpTo(base.length)

  return result
}
"}

