{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import * as fs from 'node:fs'
import { Failure, parseMode, readStdin, splitLines, splitParts } from './input.js'
import { mergeDocuments } from './merge.js'
import { hasConflict, renderMerge, renderRegions } from './render.js'

function writeAll(fd, text) {
  const data = Buffer.from(text, 'utf8')
  let written = 0
  while (written < data.length) {
    written += fs.writeSync(fd, data, written, data.length - written)
  }
}

function run(argv) {
  const mode = parseMode(argv)
  const [mine, base, theirs] = splitParts(splitLines(readStdin()))
  const regions = mergeDocuments(mine, base, theirs)
  const lines =
    mode === 'regions' ? renderRegions(regions) : renderMerge(regions, mode === 'merge')
  return {
    out: lines.map(line => `${line}\n`).join(''),
    code: hasConflict(regions) ? 1 : 0,
  }
}

try {
  const { out, code } = run(process.argv.slice(2))
  writeAll(1, out)
  process.exit(code)
} catch (err) {
  writeAll(2, `${err instanceof Failure ? err.message : `error: ${err.message}`}\n`)
  process.exit(2)
}
"}

