 * report the three-way merge of the second into the first and the third.
 */

import * as readline from 'readline';

// Parse command line arguments
const mode = process.argv[2];
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n');
  process.exit(2);
}

// Read stdin
async function readInput() {
  const rl = readline.createInterface({
    input: process.stdin,
    crlfDelay: Infinity,
  });

  const lines = [];
  for await (const line of rl) {
    lines.push(line);
  }

  // Split by %%%
  const parts = [[], [], []];
  let currentPart = 0;
  for (const line of lines) {
    if (line === '%%%') {
      currentPart++;
      if (currentPart > 2) {
        process.stderr.write('error: expected three parts separated by %%%\n');
        process.exit(2);
      }
    } else {
      parts[currentPart].push(line);
    }
  }

  if (currentPart !== 2) {
    process.stderr.write('error: expected three parts separated by %%%\n');
    process.exit(2);
  }

  return parts;
}

// Longest Common Subsequence with early-match preference
function lcs(a, b) {
  // Returns array of indices in a that form the LCS
  const n = a.length;
  const m = b.length;

  // Use greedy approach: walk from start of both, match when possible
  const result = [];
  let i = 0;
  let j = 0;

  while (i < n && j < m) {
    if (a[i] === b[j]) {
      result.push(i);
      i++;
      j++;
    } else {
      // Advance the side with more remaining elements
      const remainingA = n - i;
      const remainingB = m - j;
      if (remainingA > remainingB) {
        i++;
      } else if (remainingB > remainingA) {
        j++;
      } else {
        // Tie: prefer advancing base (for diff against base, this is 'a')
        i++;
      }
    }
  }

  return result;
}

// Compare a side against the base using LCS
function getDiff(side, base) {
  const indices = lcs(base, side);
  const indicesSet = new Set(indices);

  const changes = [];
  let baseIdx = 0;
  let sideIdx = 0;

  for (let i = 0; i <= indices.length; i++) {
    const nextBaseIdx = i < indices.length ? indices[i] : base.length;

    // Lines from baseIdx to nextBaseIdx (not including nextBaseIdx) are not in LCS
    if (baseIdx < nextBaseIdx || sideIdx < (i < indices.length ? indices.indexOf(indices[i]) : side.length)) {
      // Actually, we need to find where we are in side
      let nextSideIdx = sideIdx;
      // Count how many elements in side matched so far
      let matchedCount = 0;
      for (let j = 0; j < i; j++) {
        nextSideIdx++;
      }

      // Actually, let me reconsider the algorithm...
      baseIdx = nextBaseIdx;
    }

    if (i < indices.length) {
      baseIdx = indices[i] + 1;
      sideIdx = i + 1;
    }
  }

  return changes;
}

// Better LCS implementation that tracks position in both sequences
function getLCSIndices(base, side) {
  const n = base.length;
  const m = side.length;

  // Greedy LCS: walk from start, match when equal
  const baseIndices = [];
  const sideIndices = [];
  let i = 0;
  let j = 0;

  while (i < n && j < m) {
    if (base[i] === side[j]) {
      baseIndices.push(i);
      sideIndices.push(j);
      i++;
      j++;
    } else {
      const remainingBase = n - i;
      const remainingSide = m - j;
      if (remainingBase > remainingSide) {
        i++;
      } else if (remainingSide > remainingBase) {
        j++;
      } else {
        i++;
      }
    }
  }

  return { baseIndices, sideIndices };
}

// Get changes (hunks) from comparing side against base
function getChanges(side, base) {
  const { baseIndices, sideIndices } = getLCSIndices(base, side);
  const changes = [];

  let lastBaseIdx = 0;
  let lastSideIdx = 0;

  for (let i = 0; i < baseIndices.length; i++) {
    const currBaseIdx = baseIndices[i];
    const currSideIdx = sideIndices[i];

    // Lines between lastBaseIdx and currBaseIdx in base map to lines between lastSideIdx and currSideIdx in side
    if (lastBaseIdx !== currBaseIdx || lastSideIdx !== currSideIdx) {
      changes.push({
        baseStart: lastBaseIdx,
        baseEnd: currBaseIdx,
        sideStart: lastSideIdx,
        sideEnd: currSideIdx,
      });
    }

    lastBaseIdx = currBaseIdx + 1;
    lastSideIdx = currSideIdx + 1;
  }

  // Handle remaining lines
  if (lastBaseIdx !== base.length || lastSideIdx !== side.length) {
    changes.push({
      baseStart: lastBaseIdx,
      baseEnd: base.length,
      sideStart: lastSideIdx,
      sideEnd: side.length,
    });
  }

  // Filter out empty changes
  return changes.filter(
    (c) => c.baseStart !== c.baseEnd || c.sideStart !== c.sideEnd
  );
}

// Group overlapping changes into regions
function getRegions(mineChanges, theirsChanges, base) {
  // Merge and sort changes
  const allChanges = [
    ...mineChanges.map((c) => ({ ...c, side: 'mine' })),
    ...theirsChanges.map((c) => ({ ...c, side: 'theirs' })),
  ];

  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) {
      return a.baseStart - b.baseStart;
    }
    return a.side === 'mine' ? -1 : 1;
  });

  const regions = [];

  let i = 0;
  while (i < allChanges.length) {
    const region = {
      baseStart: allChanges[i].baseStart,
      baseEnd: allChanges[i].baseEnd,
      changes: [allChanges[i]],
    };

    // Absorb overlapping changes
    let j = i + 1;
    while (j < allChanges.length && allChanges[j].baseStart <= region.baseEnd) {
      region.changes.push(allChanges[j]);
      region.baseEnd = Math.max(region.baseEnd, allChanges[j].baseEnd);
      j++;
    }

    regions.push(region);
    i = j;
  }

  return regions;
}

