// by flattened [b0,s0,b1,s1,...]
function brute(a,b){
  let best=null
  const rec=(i,j,acc)=>{
    if(i>=a.length||j>=b.length){
      if(best===null||acc.length>best.length||(acc.length===best.length&&flat(acc)<flat(best))) best=acc.slice()
      return
    }
    if(a[i]===b[j]){rec(i+1,j+1,[...acc,[i,j]])}
    rec(i+1,j,acc); rec(i,j+1,acc)
  }
  const flat=x=>x.flat().join(',')
  rec(0,0,[])
  return best
}
